middle?:null,$last,$dob?:null,$class,$stream?:null,$scholar,$guardian?:null,$phone?:null]);$pid=(int)$db->lastInsertId();$q=$db->prepare('INSERT INTO pupil_class_history(pupil_id,school_id,class_level,academic_year,changed_by) VALUES(?,?,?,?,?)');$q->execute([$pid,$school,$class,(int)date('Y'),$uid]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'register','pupil',$pid,json_encode(['school_id'=>$school,'admission_number'=>$admission,'class_level'=>$class],JSON_THROW_ON_ERROR)]);$db->commit();$notice='Pupil registered.';}elseif($action==='link_guardian'){
