    if(!in_array($role,['admin','director','sub_director','headteacher'],true))throw new DomainException('Only school administrators can create pupil accounts.');$pupilId=(int)($_POST['pupil_id']??0);$identifier=strtolower(trim((string)($_POST['identifier']??'')));$email=filter_var($identifier,FILTER_VALIDATE_EMAIL)?$identifier:null;$username=$email?null:$identifier;if(!$pupilId||($email===null&&!preg_match('/^[a-z0-9._-]{3,60}$/',$username)))throw new DomainException('Choose a pupil and enter a valid email or username.');$q=$db->prepare("SELECT id,first_name,middle_name,last_name FROM pupils WHERE id=? AND school_id=? AND status='active'");$q->execute([$pupilId,$school]);$pupilAccount=$q->fetch();if(!$pupilAccount)throw new DomainException('Choose an active pupil in this school.');$db->beginTransaction();$q=$db->prepare('SELECT id,active FROM pupil_accounts WHERE pupil_id=? AND school_id=? FOR UPDATE');$q->execute([$pupilId,$school]);$existingLink=$q->fetch();if($existingLink&&!empty($existingLink['active']))throw new DomainException('This pupil already has an active portal account.');$q=$db->prepare('SELECT id,role,status FROM users WHERE email=? OR username=? LIMIT 1');$q->execute([$email??$identifier,$username??$identifier]);$account=$q->fetch();$temporaryPassword=null;if($account){if($account['role']!=='pupil'||$account['status']!=='active')throw new DomainException('That sign-in ID belongs to a non-pupil or inactive account.');$learnerId=(int)$account['id'];}else{$alphabet='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';$temporaryPassword='';for($i=0;$i<12;$i++)$temporaryPassword.=$alphabet[random_int(0,strlen($alphabet)-1)];$learnerName=trim($pupilAccount['first_name'].' '.$pupilAccount['middle_name'].' '.$pupilAccount['last_name']);$q=$db->prepare('INSERT INTO users(name,email,username,password_hash,role,must_change_password) VALUES(?,?,?,?,?,?)');$q->execute([$learnerName,$email,$username,password_hash($temporaryPassword,PASSWORD_DEFAULT),'pupil',1]);$learnerId=(int)$db->lastInsertId();}$q=$db->prepare('SELECT id,pupil_id,active FROM pupil_accounts WHERE user_id=? FOR UPDATE');$q->execute([$learnerId]);$userLink=$q->fetch();if($userLink&&((int)$userLink['pupil_id']!==$pupilId||!empty($userLink['active'])))throw new DomainException('That account is already assigned to another active or historical pupil link.');if($existingLink){if((int)$existingLink['id']!==(int)($userLink['id']??0))throw new DomainException('A different pupil account is already linked to this pupil.');$q=$db->prepare('UPDATE pupil_accounts SET active=1,linked_by=?,revoked_by=NULL,revoked_at=NULL WHERE id=? AND school_id=?');$q->execute([$uid,$existingLink['id'],$school]);$accountId=(int)$existingLink['id'];}else{$q=$db->prepare('INSERT INTO pupil_accounts(school_id,pupil_id,user_id,linked_by) VALUES(?,?,?,?)');$q->execute([$school,$pupilId,$learnerId,$uid]);$accountId=(int)$db->lastInsertId();}$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'link_pupil_account','pupil_account',$accountId,json_encode(['school_id'=>$school,'pupil_id'=>$pupilId,'user_id'=>$learnerId],JSON_THROW_ON_ERROR)]);$db->commit();$_SESSION['learner_account_notice']=['name'=>trim($pupilAccount['first_name'].' '.$pupilAccount['last_name']),'identifier'=>$identifier,'password'=>$temporaryPassword];header('Location: pupils.php?school_id='.$school);exit;
}elseif($action==='revoke_pupil_account'){
    if(!in_array($role,['admin','director','sub_director','headteacher'],true))throw new DomainException('Only school administrators can revoke pupil accounts.');$accountId=(int)($_POST['account_id']??0);$db->beginTransaction();$q=$db->prepare('SELECT id,pupil_id,user_id FROM pupil_accounts WHERE id=? AND school_id=? AND active=1 FOR UPDATE');$q->execute([$accountId,$school]);$linkedAccount=$q->fetch();if(!$linkedAccount)throw new DomainException('That active pupil account is outside this school.');$q=$db->prepare('UPDATE pupil_accounts SET active=0,revoked_by=?,revoked_at=CURRENT_TIMESTAMP WHERE id=? AND school_id=? AND active=1');$q->execute([$uid,$accountId,$school]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'revoke_pupil_account','pupil_account',$accountId,json_encode(['school_id'=>$school,'pupil_id'=>(int)$linkedAccount['pupil_id'],'user_id'=>(int)$linkedAccount['user_id']],JSON_THROW_ON_ERROR)]);$db->commit();$_SESSION['learner_account_notice']=['message'=>'Pupil portal access was revoked.'];header('Location: pupils.php?school_id='.$school);exit;
}elseif($action==='promote'){if(!in_array($role,['director','sub_director','headteacher','head_academic'],true))throw new DomainException('Your role cannot promote pupils.');$from=trim((string)($_POST['from_class']??''));$to=trim((string)($_POST['to_class']??''));$year=filter_var($_POST['academic_year']??null,FILTER_VALIDATE_INT);if(!$from||!$to||$from===$to||$year===false||$year<2000||$year>2100)throw new DomainException('Choose two different classes and a valid academic year.');$q=$db->prepare('SELECT COUNT(*) FROM school_classes WHERE school_id=? AND name IN (?,?)');$q->execute([$school,$from,$to]);if((int)$q->fetchColumn()!==2)throw new DomainException('Both classes must belong to this school.');$db->beginTransaction();$q=$db->prepare("SELECT id FROM pupils WHERE school_id=? AND class_level=? AND status='active' FOR UPDATE");$q->execute([$school,$from]);$moving=$q->fetchAll(PDO::FETCH_COLUMN);if(!$moving)throw new DomainException('No active pupils are in that class.');$history=$db->prepare('INSERT INTO pupil_class_history(pupil_id,school_id,class_level,academic_year,changed_by) VALUES(?,?,?,?,?)');foreach($moving as $pid)$history->execute([(int)$pid,$school,$to,$year,$uid]);$q=$db->prepare("UPDATE pupils SET class_level=?,stream=NULL WHERE school_id=? AND class_level=? AND status='active'");$q->execute([$to,$school,$from]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'promote','pupil_class',$school,json_encode(['school_id'=>$school,'from_class'=>$from,'to_class'=>$to,'academic_year'=>$year,'pupils_moved'=>count($moving)],JSON_THROW_ON_ERROR)]);$db->commit();$notice=count($moving).' pupils promoted to '.$to.'. Assign their streams in school setup.';}else throw new DomainException('Choose a valid action.');}catch(DomainException $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}catch(PDOException $e){if($db->inTransaction())$db->rollBack();$error=$e->getCode()==='230