$filter=trim((string)($_GET['class']??''));$search=trim((string)($_GET['q']??''));$sql='SELECT * FROM pupils WHERE school_id=?';$args=[$school];if($filter!==''){$sql.=' AND class_level=?';$args[]=$filter;}if($search!==''){$sql.=' AND (first_name LIKE ? OR middle_name LIKE ? OR last_name LIKE ? OR admission_number LIKE ?)';$like='%'.$search.'%';array_push($args,$like,$like,$like,$like);}$sql.=' ORDER BY class_level,last_name,first_name LIMIT 500';$q=$db->prepare($sql);$q->execute($args);$pupils=$q->fetchAll();$guardiansByPupil=[];if($pupils){$idsForGuardians=array_map('intval',array_column($pupils,'id'));$marks=implode(',',array_fill(0,count($idsForGuardians),'?'));$g=$db->prepare("SELECT pg.id link_id,pg.pupil_id,u.name,pg.relationship,pg.is_primary FROM pupil_guardians pg JOIN users u ON u.id=pg.guardian_user_id WHERE pg.school_id=? AND pg.pupil_id IN ($marks) ORDER BY pg.is_primary DESC,u.name");$g->execute(array_merge([$school],$idsForGuardians));foreach($g->fetchAll() as $guardian)$guardiansByPupil[(int)$guardian['pupil_id']][]=$guardian;}$guardianPupilOptions=[];if(in_array($role,['admin','director','sub_director','headteacher'],true)){$q=$db->prepare("SELECT id,admission_number,first_name,last_name,class_level FROM pupils WHERE school_id=? AND status='active' ORDER BY class_level,last_name");$q->execute([$school]);$guardianPupilOptions=$q->fetchAll();}$pupilAccounts=[];if($pupils){$accountPupilIds=array_map('intval',array_column($pupils,'id'));$accountMarks=implode(',',array_fill(0,count($accountPupilIds),'?'));$q=$db->prepare("SELECT id,pupil_id,active FROM pupil_accounts WHERE school_id=? AND pupil_id IN ($accountMarks)");$q->execute(array_merge([$school],$accountPupilIds));foreach($q->fetchAll() as $accountRow)$pupilAccounts[(int)$accountRow['pupil_id']]=$accountRow;}
