<?php if($guardianAccount):?><div class="notice success" role="status"><strong>Parent linked to pupil.</strong> Sign-in ID: <strong><?=e($guardianAccount['identifier'])?></strong>. <?php if($guardianAccount['password']):?>Temporary password: <code><?=e($guardianAccount['password'])?></code>. Share it securely; the parent must change it after signing in.<?php else:?>The existing parent account remains active.<?php endif;?></div><?php endif;?><?php if($learnerAccount):?><div class="notice success" role="status"><?php if(isset($learnerAccount['message'])):?><?=e($learnerAccount['message'])?><?php else:?><strong>Learner account linked.</strong> Sign-in ID: <strong><?=e($learnerAccount['identifier'])?></strong>. <?php if($learnerAccount['password']):?>Temporary password: <code><?=e($learnerAccount['password'])?></code>. Share it with the learner and require a password change after sign-in.<?php else:?>The existing pupil account has been reactivated.<?php endif;?><?php endif;?></div><?php endif;?><?php if(in_array($role,['admin','director','sub_director','headteacher'],true)):?><section class="note-create"><div class="section-heading"><div><div class="eyebrow">PARENT PORTAL ACCESS</div><h2>Link an authorized parent or guardian</h2><p class="muted">This creates a parent account or links an existing parent account. Confirm the guardian’s identity before linking.</p></div></div><?php if($guardianPupilOptions):?><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="link_guardian"><input type="hidden" name="school_id" value="<?=$school?>"><div class="form-grid"><div><label for="guardian-pupil">Pupil</label><select id="guardian-pupil" name="pupil_id" required><?php foreach($guardianPupilOptions as $pupilOption):?><option value="<?=$pupilOption['id']?>"><?=e($pupilOption['admission_number'].' · '.$pupilOption['first_name'].' '.$pupilOption['last_name'].' · '.$pupilOption['class_level'])?></option><?php endforeach;?></select></div><div><label for="guardian-account-name">Parent / guardian name</label><input id="guardian-account-name" name="guardian_name" maxlength="140" required></div><div><label for="guardian-identifier">Parent email or username</label><input id="guardian-identifier" name="identifier" maxlength="190" autocomplete="off" required></div><div><label for="guardian-account-phone">Phone (optional)</label><input id="guardian-account-phone" name="guardian_phone" type="tel" maxlength="30"></div><div><label for="guardian-relationship">Relationship</label><input id="guardian-relationship" name="relationship" value="Guardian" maxlength="50" required></div></div><label><input type="checkbox" name="is_primary" value="1"> Set as primary guardian</label> <label><input type="checkbox" name="receives_notifications" value="1" checked> Allow school notifications</label><p><button class="button primary" type="submit">Link parent portal account</button></p></form><?php else:?><p class="muted">Register an active pupil before linking a guardian account.</p><?php endif;?></section><?php endif;?><?php if(in_array($role,['admin','director','sub_director','headteacher'],true)):?><section class="note-create"><div class="section-heading"><div><div class="eyebrow">LEARNER PORTAL ACCESS</div><h2>Create or restore a pupil account</h2><p class="muted">Pupil accounts can access only their own published results, attendance summary and published class materials.</p></div></div><?php if($guardianPupilOptions):?><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create_pupil_account"><input type="hidden" name="school_id" value="<?=$school?>"><div class="form-grid"><div><label for="account-pupil">Pupil</label><select id="account-pupil" name="pupil_id" required><?php foreach($guardianPupilOptions as $pupilOption):?><option value="<?=$pupilOption['id']?>"><?=e($pupilOption['admission_number'].' · '.$pupilOption['first_name'].' '.$pupilOption['last_name'].' · '.$pupilOption['class_level'])?></option><?php endforeach;?></select></div><div><label for="pupil-identifier">Pupil email or username</label><input id="pupil-identifier" name="identifier" maxlength="190" required></div></div><button class="button primary" type="submit">Create learner account</button></form><?php else:?><p class="muted">Register an active pupil before creating a learner account.</p><?php endif;?></section><?php endif;?>
<?php if($canImportPupils):?><section class="note-create"><div class="section-heading"><div><div class="eyebrow">BULK ENROLMENT</div><h2>Import pupils from CSV</h2></div><a class="button" href="pupil_template.php?school_id=<?=$school?>">Download CSV template</a></div><p class="muted">Imports up to 500 pupil rows in one transaction. If any row is invalid or an admission number already exists, the whole file is rejected without partial imports. Full Names are split into first, middle, and last name fields.</p><form data-pupil-import-form enctype="multipart/form-data"><input type="hidden" name="school_id" value="<?=$school?>"><label for="pupil-csv">CSV file</label><input id="pupil-csv" type="file" name="pupil_csv" accept=".csv,text/csv" required><button class="button primary" type="submit">Validate and import</button></form><div data-pupil-import-result role="status" aria-live="polite"></div></section><?php endif;?><section class="note-create"><div class="section-heading"><div><div class="eyebrow">NEW ENROLMENT</div><h2>Register a pupil</h2></div></div><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="register"><input type="hidden" name="school_id" value="<?=$school?>"><div class="form-grid"><div><label for="admission">Admission number</label><input id="admission" name="admission_number" maxlength="60" required></div><div><label for="first">First name</label><input id="first" name="first_name" maxlength="80" required></div><div><label for="middle">Middle name</label><input id="middle" name="middle_name" maxlength="80"></div><div><label for="last">Last name</label><input id="last" name="last_name" maxlength="80" required></div><div><label for="dob">Date of birth</label><input id="dob" type="date" name="date_of_birth"></div><div><label for="class">Class</label><select id="class" name="class_level" required><option value="">Choose class</option><?php foreach($classes as $c):?><option value="<?=e($c['name'])?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div><label for="stream">Stream</label><select id="stream" name="stream"><option value="">No stream</option><?php foreach($classes as $c):$sq=$db->prepare('SELECT name FROM school_streams WHERE class_id=? ORDER BY name');$sq->execute([$c['id']]);foreach($sq->fetchAll(PDO::FETCH_COLUMN) as $st):?><option data-class="<?=e($c['name'])?>" value="<?=e($st)?>"><?=e($c['name'].' · '.$st)?></option><?php endforeach;endforeach;?></select></div><div><label for="scholar">Day or boarding</label><select id="scholar" name="scholar_type"><option value="day">Day</option><option value="boarding">Boarding</option></select></div><div><label for="guardian">Parent / guardian</label><input id="guardian" name="guardian_name" maxlength="140"></div><div><label for="phone">Guardian phone</label><input id="phone" type="tel" name="guardian_phone" maxlength="30"></div></div><button class="button primary" type="submit">Register pupil</button></form></section>
<?php if(in_array($role,['director','sub_director','headteacher','head_academic'],true)):?><section class="note-create"><div class="section-heading"><div><div class="eyebrow">YEAR-END PROGRESSION</div><h2>Promote a class</h2></div></div><p class="muted">Moves active pupils together, clears old streams, retains class history and logs the change.</p><form method="post" class="note-form" onsubmit="return confirm('Promote every active pupil in this class? Their stream assignments will be cleared.');"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="promote"><input type="hidden" name="school_id" value="<?=$school?>"><div class="form-grid"><div><label for="from">From class</label><select id="from" name="from_class" required><?php foreach($classes as $c):?><option value="<?=e($c['name'])?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div><label for="to">Promote to</label><select id="to" name="to_class" required><?php foreach($classes as $c):?><option value="<?=e($c['name'])?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div><label for="year">Academic year</label><input id="year" type="number" name="academic_year" min="2000" max="2100" value="<?=date('Y')?>" required></div></div><button class="button primary" type="submit">Promote pupils</button></form></section><?php endif;?>
<section class="content-section" id="pupil-directory"><div class="section-heading"><div><div class="eyebrow">SCHOOL DIRECTORY</div><h2>Enrolled pupils</h2></div><span class="count-pill"><?=count($pupils)?> shown</span></div><form method="get" class="ops-filter"><input type="hidden" name="school_id" value="<?=$school?>"><div><label for="q">Search name or admission number</label><input id="q" type="search" name="q" value="<?=e($search)?>"></div><div><label for="class-filter">Class</label><select id="class-filter" name="class"><option value="">All classes</option><?php foreach($classes as $c):?><option value="<?=e($c['name'])?>"<?=$filter===$c['name']?' selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><button class="button" type="submit">Find pupils</button></form><?php if($pupils):?><div class="table-wrap"><table><thead><tr><th>Admission</th><th>Name</th><th>Class / stream</th><th>Type</th><th>Guardian</th><th>Status</th><th>Learner portal</th></tr></thead><tbody><?php foreach($pupils as $p):?><tr><td><?=e($p['admission_number'])?></td><td><span data-pupil-name><?=e(trim($p['first_name'].' '.$p['middle_name'].' '.$p['last_name']))?></span><?php if($canManagePupilStatus):?> <button class="button" type="button" data-pupil-edit data-pupil-id="<?=$p['id']?>" data-first="<?=e($p['first_name'])?>" data-middle="<?=e($p['middle_name']??'')?>" data-last="<?=e($p['last_name'])?>" data-dob="<?=e((string)($p['date_of_birth']??''))?>" data-scholar="<?=e($p['scholar_type'])?>" data-guardian="<?=e($p['guardian_name']??'')?>" data-phone="<?=e($p['guardian_phone']??'')?>">Edit profile</button><?php endif;?></td><td><?=e($p['class_level'].($p['stream']?' · '.$p['stream']:''))?></td><td><span data-pupil-scholar><?=e(ucfirst($p['scholar_type']))?></span></td><td><?php if(!empty($guardiansByPupil[(int)$p['id']])):?><?php foreach($guardiansByPupil[(int)$p['id']] as $guardian):?><?=e($guardian['name'].' · '.$guardian['relationship'].(!empty($guardian['is_primary'])?' (primary)':''))?><?php if(in_array($role,['admin','director','sub_director','headteacher'],true)):?><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="unlink_guardian"><input type="hidden" name="school_id" value="<?=$school?>"><input type="hidden" name="guardian_link_id" value="<?=$guardian['link_id']?>"><button class="button" type="submit">Remove access</button></form><?php endif;?><br><?php endforeach;?><?php else:?><span data-pupil-contact><?=e(trim(($p['guardian_name']??'').' '.($p['guardian_phone']??''))?:'—')?></span><?php endif;?></td><td><span data-pupil-status-label><?=e(ucfirst($p['status']))?></span><?php if($canManagePupilStatus):?> <button class="button" type="button" data-pupil-status data-pupil-id="<?=$p['id']?>" data-admission="<?=e($p['admission_number'])?>" data-current-status="<?=e($p['status'])?>">Update status</button> <button class="button" type="button" data-pupil-history data-pupil-id="<?=$p['id']?>" data-admission="<?=e($p['admission_number'])?>">History</button><?php endif;?></td><td><?php $pupilAccount=$pupilAccounts[(int)$p['id']]??null;if($pupilAccount&&!empty($pupilAccount['active'])):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="revoke_pupil_account"><input type="hidden" name="school_id" value="<?=$school?>"><input type="hidden" name="account_id" value="<?=$pupilAccount['id']?>"><button class="button" type="submit">Revoke access</button></form><?php elseif($pupilAccount):?>Inactive<?php else:?>Not created<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No matching pupils</h3><p>Register a pupil or adjust the search filters.</p></div><?php endif;?></section><dialog id="pupil-profile-dialog"><form data-pupil-profile-form><input type="hidden" name="pupil_id"><input type="hidden" name="school_id" value="<?=$school?>"><div class="section-heading"><div><div class="eyebrow">PUPIL DIRECTORY</div><h2 id="pupil-profile-title">Edit pupil profile</h2></div></div><div class="form-grid"><div><label for="profile-first">First name</label><input id="profile-first" name="first_name" maxlength="80" required></div><div><label for="profile-middle">Middle name</label><input id="profile-middle" name="middle_name" maxlength="80"></div><div><label for="profile-last">Last name</label><input id="profile-last" name="last_name" maxlength="80" required></div><div><label for="profile-dob">Date of birth</label><input id="profile-dob" name="date_of_birth" type="date" max="<?=date('Y-m-d')?>"></div><div><label for="profile-scholar">Day or boarding</label><select id="profile-scholar" name="scholar_type"><option value="day">Day</option><option value="boarding">Boarding</option></select></div><div><label for="profile-guardian">Registration contact name</label><input id="profile-guardian" name="guardian_name" maxlength="140"></div><div><label for="profile-phone">Registration contact phone</label><input id="profile-phone" name="guardian_phone" type="tel" maxlength="30"></div></div><p class="muted">Admission number and class placement are unchanged here. Use year-end promotion to record class changes. Registration contact details do not change linked parent portal accounts.</p><div class="ops-actions"><button class="button primary" type="submit">Save profile</button><button class="button" type="button" data-close-pupil-profile>Cancel</button></div><p data-pupil-profile-message role="status" aria-live="polite"></p></form></dialog><dialog id="pupil-status-dialog"><form data-pupil-status-form><input type="hidden" name="pupil_id"><input type="hidden" name="school_id" value="<?=$school?>"><div class="section-heading"><div><div class="eyebrow">ENROLMENT LIFECYCLE</div><h2 id="pupil-status-title">Update pupil status</h2></div></div><p class="muted" data-pupil-status-current></p><div class="form-grid"><div><label for="pupil-new-status">New status</label><select id="pupil-new-status" name="new_status" required></select></div><div><label for="pupil-status-date">Effective date</label><input id="pupil-status-date" type="date" name="effective_date" value="<?=date('Y-m-d')?>" max="<?=date('Y-m-d')?>" required></div><div class="form-span"><label for="pupil-status-note">Optional note</label><textarea id="pupil-status-note" name="note" maxlength="500" rows="3"></textarea></div></div><div class="ops-actions"><button class="button primary" type="submit">Save status</button><button class="button" type="button" data-close-pupil-status>Cancel</button></div><p data-pupil-status-message role="status" aria-live="polite"></p></form></dialog><dialog id="pupil-status-history-dialog"><div class="section-heading"><div><div class="eyebrow">ENROLMENT HISTORY</div><h2 id="pupil-status-history-title">Status history</h2></div></div><div id="pupil-status-history-output" aria-live="polite"></div><button class="button" type="button" data-close-pupil-history>Close</button></dialog><footer class="page-footer">ShuleLite <span>·</span> Pupil records</footer></div></main></div><script>const c=document.querySelector('#class'),s=document.querySelector('#stream');function fs(){for(const o of s.options)if(o.dataset.class){o.hidden=o.dataset.class!==c.value;if(o.hidden&&o.selected)s.value=''}}c.addEventListener('change',fs);fs()</script></body></html>
